<?php
/**
 * Flower-specific return and claim wording for the generated legal documents.
 *
 * This deliberately avoids an arbitrary "24 hour" cutoff. For distance sales,
 * the decisive points are the condition of the goods, preservation of their
 * consumer properties and the cause/time at which a defect arose.
 *
 * @package Cvetochny_Gorod
 */

if (!defined('ABSPATH')) exit;

/**
 * Replace only the generated Returns & Claims document with flower-specific
 * wording. Other legal shortcodes keep their original output.
 */
function cg_legal_flower_returns_document($output, $tag, $attr, $m) {
    if ($tag !== 'cg_legal_document') return $output;
    if (!is_array($attr) || sanitize_key($attr['type'] ?? '') !== 'returns') return $output;
    if (!function_exists('cg_legal_get_settings') || !function_exists('cg_legal_document_header')) return $output;

    $s = cg_legal_get_settings();
    $version = !empty($s['offer_version']) ? $s['offer_version'] : wp_date('d.m.Y');

    $html = '<article class="cg-legal-document">';
    $html .= cg_legal_document_header('Возврат и претензии', $version);

    $html .= '<section><h2>1. Отказ от заказа до вручения</h2>';
    $html .= '<p>Если заказ оформлен дистанционно, покупатель вправе отказаться от товара до его передачи получателю. Если заказ уже передан курьеру или понесены иные фактические расходы, вопрос о таких расходах решается в соответствии с законом и условиями конкретного заказа.</p></section>';

    $html .= '<section><h2>2. Возврат букета надлежащего качества после вручения</h2>';
    $html .= '<p>Для товаров, заказанных через сайт или иным дистанционным способом, применяются правила статьи 26.1 Закона РФ «О защите прав потребителей». Возврат товара надлежащего качества после передачи возможен только при сохранении его товарного вида и потребительских свойств, с учетом иных предусмотренных законом условий.</p>';
    $html .= '<p><strong>Срезанные цветы являются скоропортящимся живым товаром, состояние которого напрямую зависит от температуры, воды, освещения и ухода после вручения.</strong> Если после передачи букет утратил свежесть, товарный вид или иные потребительские свойства вследствие обезвоживания, нахождения рядом с батареей или иным источником тепла, под прямыми солнечными лучами, на морозе, в душном помещении, на сквозняке, без воды либо вследствие механических повреждений после передачи, такой случай сам по себе не свидетельствует о недостатке товара, существовавшем на момент вручения.</p>';
    $html .= '<p>Фиксированный срок вроде «24 часов» не используется: при рассмотрении обращения оцениваются состояние букета при передаче, соблюдение условий хранения и ухода, характер повреждений и иные обстоятельства конкретного случая.</p></section>';

    $html .= '<section><h2>3. Проверка состояния при вручении</h2>';
    $html .= '<p>Получателю рекомендуется осмотреть букет при получении: количество и вид цветов, свежесть, отсутствие сломанных стеблей и видимых повреждений, соответствие согласованному заказу. Магазин вправе фиксировать внешний вид готового букета фотографией до отправки и при необходимости использовать ее при рассмотрении претензии.</p>';
    $html .= '<p>Если видимый недостаток обнаружен при вручении или сразу после него, просим как можно быстрее связаться с магазином и, по возможности, приложить фотографии. Это помогает установить фактическое состояние товара и причину недостатка. Такая просьба не ограничивает права потребителя, предоставленные законом.</p></section>';

    $html .= '<section><h2>4. Условия ухода после получения</h2>';
    $html .= '<p>После передачи букета покупатель или получатель отвечает за обычные условия его хранения и ухода. Для сохранения свежести рекомендуется обеспечить достаточное количество чистой прохладной воды (или поддерживать влажность флористической губки в композиции), не оставлять цветы без воды, держать их вдали от прямого солнца, батарей, обогревателей, сильного холода, кондиционеров и резких перепадов температуры. Для букетов в вазе рекомендуется регулярно менять воду и обновлять срез стеблей, если это применимо к конкретной композиции.</p>';
    $html .= '<p>Ухудшение состояния товара после передачи вследствие нарушения условий хранения, транспортировки самим получателем, неправильного ухода либо иных обстоятельств, возникших после вручения и не зависящих от продавца, не является основанием для возложения на продавца ответственности за качество товара.</p></section>';

    $html .= '<section><h2>5. Если недостаток существовал при передаче</h2>';
    $html .= '<p>Если букет был передан с недостатком, который не был оговорен заранее (например, сломанные цветы, существенное несоответствие согласованному составу или количеству, явное ненадлежащее состояние цветов), покупатель вправе заявить требования, предусмотренные законодательством о защите прав потребителей. Ухудшение качества по вине продавца или привлеченного им курьера также рассматривается в установленном законом порядке.</p>';
    $html .= '<p>Магазин вправе провести проверку качества и установить причины ухудшения товара. Права покупателя и обязанности продавца при споре о причинах возникновения недостатков определяются законодательством РФ.</p></section>';

    $html .= '<section><h2>6. Индивидуально изготовленные композиции</h2>';
    $html .= '<p>Если композиция была изготовлена специально под конкретного покупателя по индивидуально согласованным параметрам и обладает индивидуально-определенными свойствами, к ней может применяться предусмотренное законом исключение для товара надлежащего качества, который может быть использован исключительно приобретающим его потребителем. Наличие таких свойств оценивается применительно к конкретному заказу; это положение не используется как автоматический отказ по любому букету.</p></section>';

    $html .= '<section><h2>7. Как направить претензию</h2>';
    $html .= '<p>Обращение можно направить на e-mail ' . esc_html($s['email'] ?: 'продавца') . ' или по адресу: ' . esc_html($s['claim_address'] ?: 'адрес для претензий не заполнен') . '. Укажите номер заказа, дату и время получения, описание ситуации и требование. Для вопросов о свежести цветов желательно приложить фотографии букета целиком и проблемных цветов, сделанные как можно раньше после обнаружения проблемы.</p></section>';

    $html .= '<section><h2>8. Возврат денежных средств</h2>';
    $html .= '<p>Если требование о возврате денежных средств подлежит удовлетворению, возврат производится в сроки и порядке, установленные законодательством РФ и правилами соответствующего способа оплаты. Настоящий документ не ограничивает права потребителя в случаях, когда такие права прямо предусмотрены законом.</p></section>';

    $html .= '</article>';
    return $html;
}
add_filter('do_shortcode_tag', 'cg_legal_flower_returns_document', 20, 4);

/** Add the customer care/returns memo to emails, orders and the print workflow. */
require_once get_template_directory() . '/inc/customer-buyer-memo.php';

/** Keep the compact buyer memo limited to phone number and opening hours. */
require_once get_template_directory() . '/inc/customer-buyer-memo-contact-cleanup.php';